package com.agenthitler;
import android.content.*; import android.os.Bundle; import android.speech.*; import android.util.Log; import java.util.*;
public final class AndroidSpeechRecognizer implements SpeechRecognizerEngine {
 private final Context context; private SpeechRecognizer recognizer; private Callback callback;
 public AndroidSpeechRecognizer(Context c){context=c.getApplicationContext();}
 public void start(Callback cb){callback=cb;try{if(recognizer!=null)recognizer.destroy(); recognizer=SpeechRecognizer.createSpeechRecognizer(context);recognizer.setRecognitionListener(new RecognitionListener(){public void onReadyForSpeech(Bundle b){Log.i("AgentHitler","Speech ready");} public void onBeginningOfSpeech(){} public void onRmsChanged(float v){} public void onBufferReceived(byte[] b){} public void onEndOfSpeech(){} public void onPartialResults(Bundle b){} public void onEvent(int a,Bundle b){} public void onError(int e){Log.e("AgentHitler","Speech error "+e);if(callback!=null)callback.onResult(SpeechResult.fail("Speech error "+e));} public void onResults(Bundle b){ArrayList<String>x=b.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION);String text=x==null||x.isEmpty()?null:x.get(0);Log.i("AgentHitler","Speech result "+text);if(callback!=null)callback.onResult(text==null?SpeechResult.fail("No speech recognized"):SpeechResult.ok(text));}}); Intent i=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);i.putExtra(RecognizerIntent.EXTRA_MAX_RESULTS,3);recognizer.startListening(i);}catch(Throwable t){Log.e("AgentHitler","Speech start failed",t);cb.onResult(SpeechResult.fail("Speech start failed"));}}
 public void stop(){if(recognizer!=null)recognizer.stopListening();} public void destroy(){if(recognizer!=null){recognizer.destroy();recognizer=null;}}
}
